function norm(s){return String(s||"").normalize("NFKC").replace(/[\s\p{P}\p{S}]/gu,"");}
function recall(expected,actual){const e=[...norm(expected)],a=[...norm(actual)];let prev=new Uint16Array(a.length+1);for(const c of e){const next=new Uint16Array(a.length+1);for(let j=1;j<=a.length;j++)next[j]=c===a[j-1]?prev[j-1]+1:Math.max(prev[j],next[j-1]);prev=next;}return e.length?Number((prev[a.length]/e.length).toFixed(3)):1;}
function clipHistory(messages){let remaining=48000;const selected=[];for(const m of messages.slice(-40).reverse()){if(remaining<=0)break;const content=m.content.slice(0,remaining);remaining-=content.length;selected.push({...m,content});}return selected.reverse();}
